<span class="line"><span style="color:#F97583;">    FROM</span><span style="color:#79B8FF;"> performance_schema</span><span style="color:#E1E4E8;">.</span><span style="color:#79B8FF;">global_status</span><span style="color:#E1E4E8;"> </span></span>
